const { items, add } = useToastQueue();

function onSave() {
  add({ type: 'success', title: 'Cambios guardados', description: 'Tu perfil se actualizó.' });
}

<Toaster>
  {items.map((item) => <Toast key={item.id} {...item.props} />)}
</Toaster>

function onSync() {
  add({ type: 'info', title: 'Sincronización lista', duration: 5000 });
}
